1	// T1 three-worker A/B — standalone booted-stack RSS harness.
2	//
3	// AUTHORING STATUS: this file is design evidence for the packet
4	// `T1-claude-3worker-ab-draft-packet.md`. It has never been executed. It may not
5	// be executed until two Sol xHigh reviewers approve this exact source AND V
6	// approves the run. The SHA embedded below is the design-stage packet hash; the
7	// run wrapper must still compare the on-disk packet against the hash V approved
8	// externally before it exports `T1_N3_AB_PACKET_SHA256`.
9	//
10	// WHY THIS FILE EXISTS
11	// The policy's 368.7 MiB figure came from a Vitest-worker provenance class: a
12	// process that also holds Vitest's own runner, module graph and reporters. It is
13	// not comparable to a genuine booted product process, and it cannot be used to
14	// derive an operator memory bound. This harness is the other provenance class —
15	// one plain Node process that boots the same components `apps/api/src/main.ts`
16	// boots, in the same order, with no test runner resident. Prior standalone
17	// booted observations of 315.3/327.1 MiB belong to this class; the number this
18	// harness produces is comparable to those and to nothing else.
19	//
20	// WHAT IT MEASURES, AND WHAT IT DOES NOT
21	// It measures whole-process RSS for one selected Argon2 worker count across a
22	// fixed script: boot, ten real registrations, an exact limiter-occupancy sweep,
23	// and eight concurrent maximum-cost credential jobs. Its output is a DESCRIPTIVE
24	// resource observation. It is not a statistical cell: it contributes no paired
25	// value to the integration sign tests and no causal conclusion. Any RSS bound
26	// derived from it is an UNRATIFIED CANDIDATE until V rules on it separately.
27	//
28	// INVOCATION (by the wrapper only, never by hand):
29	//   node --expose-gc --import tsx <this file>
30	// with `T1_N3_AB_PACKET_SHA256`, `T1_N3_AB_WORKERS` and `T1_N3_AB_CELL_ID` set.
31	// There is deliberately no output-path argument: the process writes exactly one
32	// marker line to stdout and nothing else to stdout, so the wrapper owns custody
33	// of where that line lands.
34	
35	import { mkdtemp, rm } from "node:fs/promises";
36	import { monitorEventLoopDelay, performance } from "node:perf_hooks";
37	import os from "node:os";
38	import { join } from "node:path";
39	import { pathToFileURL } from "node:url";
40	
41	// ---------------------------------------------------------------------------
42	// Module-evaluation authorization gate.
43	//
44	// Everything in this block runs BEFORE a database, a worker thread or a secret
45	// directory exists. A missing or wrong token must cost nothing and leave
46	// nothing behind, so the gate is deliberately the first executable statement
47	// after the import list and constructs no product object at all.
48	// ---------------------------------------------------------------------------
49	
50	/**
51	 * SHA-256 of `T1-claude-3worker-ab-draft-packet.md` at design-stage approval.
52	 * The packet cannot contain its own hash, so the literal lives here and in the
53	 * adjudicator, and the wrapper is what binds both to V's externally recorded
54	 * approval.
55	 */
56	const EXPECTED_PACKET_SHA256 =
57	  "a1cef6fb53a178607db9eb84036c7677d9aa0b8dffbb738b8da1873f4c047503";
58	
59	/** The only lawful worker counts for this diagnostic. */
60	const LAWFUL_WORKER_COUNTS = Object.freeze(["2", "3"]);
61	
62	/**
63	 * Secret-free cell identifier. Lowercase alphanumerics, dot, dash, underscore.
64	 * The wrapper supplies something like `standalone-pair03-a-w3`; the pattern
65	 * exists so a cell label can never smuggle an address, a path or a token into
66	 * the one line this process prints.
67	 */
68	const CELL_ID_SHAPE = /^[a-z0-9][a-z0-9._-]{0,63}$/;
69	
70	/** Whole-process RSS diagnostic safety stop ruled by V. Not an operator bound. */
71	const RSS_SAFETY_LIMIT_BYTES = 512 * 1024 * 1024;
72	
73	/** Stable stdout marker. The wrapper locates the report by this prefix. */
74	const REPORT_MARKER = "[T1_N3_AB_STANDALONE_REPORT]";
75	
76	/**
77	 * The exact limiter geometry this harness asserts against. `bucket_capacity` is
78	 * 524,288 per route across the three auth routes, so a fully occupied limiter is
79	 * 1,572,864 of 1,572,864 slots. A different geometry means the governed policy
80	 * moved under the experiment, which is a custody question, not a measurement.
81	 */
82	const EXPECTED_PER_ROUTE_SLOT_CAPACITY = 524_288;
83	const EXPECTED_TOTAL_SLOT_CAPACITY = 1_572_864;
84	const AUTH_ROUTE_NAMES = Object.freeze(["register", "verify", "resend"]);
85	
86	/** Exact occupancy fractions sampled, in the order they are applied. */
87	const OCCUPANCY_STEPS = Object.freeze([
88	  Object.freeze({ label: "0", numerator: 0, denominator: 4 }),
89	  Object.freeze({ label: "25", numerator: 1, denominator: 4 }),
90	  Object.freeze({ label: "50", numerator: 2, denominator: 4 }),
91	  Object.freeze({ label: "100", numerator: 4, denominator: 4 })
92	]);
93	
94	/**
95	 * Fixed far-future epoch written into occupied slots, 2100-01-01T00:00:00Z.
96	 * A wall-clock-derived value would make the touched state depend on when the
97	 * cell ran; this constant makes the occupancy sweep byte-deterministic.
98	 */
99	const OCCUPANCY_SENTINEL_MS = 4_102_444_800_000;
100	
101	/** Registrations the booted script performs, and the exact durable row count. */
102	const REGISTRATION_COUNT = 10;
103	
104	/** Concurrent maximum-cost credential jobs, identical for both worker counts. */
105	const MAX_COST_JOB_COUNT = 8;
106	
107	/** Whole-process sampling cadence while credential work is pending. */
108	const SAMPLE_INTERVAL_MS = 5;
109	
110	/** Bounded waits, so no failure mode of this harness is an unbounded hang. */
111	const QUIESCE_TIMEOUT_MS = 180_000;
112	const WARM_UP_OBSERVE_TIMEOUT_MS = 180_000;
113	
114	class HarnessError extends Error {
115	  constructor(code) {
116	    super(code);
117	    this.name = "HarnessError";
118	    this.code = code;
119	  }
120	}
121	
122	/**
123	 * Fails the process before any resource exists.
124	 *
125	 * Thrown at module evaluation on purpose: `node --check` still parses this file,
126	 * but an unauthorized invocation dies here rather than after booting PostgreSQL.
127	 */
128	function authorize() {
129	  if (process.env.T1_N3_AB_PACKET_SHA256 !== EXPECTED_PACKET_SHA256) {
130	    throw new HarnessError("T1_N3_AB_PACKET_TOKEN_MISMATCH");
131	  }
132	  const workersRaw = process.env.T1_N3_AB_WORKERS;
133	  if (!LAWFUL_WORKER_COUNTS.includes(workersRaw)) {
134	    throw new HarnessError("T1_N3_AB_WORKER_COUNT_INVALID");
135	  }
136	  const cellId = process.env.T1_N3_AB_CELL_ID;
137	  if (typeof cellId !== "string" || !CELL_ID_SHAPE.test(cellId)) {
138	    throw new HarnessError("T1_N3_AB_CELL_ID_INVALID");
139	  }
140	  // No arbitrary output path, and no positional arguments of any kind. The only
141	  // durable artifact of a run is the wrapper-captured stdout of this process.
142	  if (process.argv.length > 2) {
143	    throw new HarnessError("T1_N3_AB_UNEXPECTED_ARGUMENT");
144	  }
145	  // The occupancy and settled-RSS readings are only interpretable after a real
146	  // major collection. Inferring gc from a flag string would let a mis-invoked
147	  // cell report unquiesced numbers as if they were quiesced.
148	  if (typeof globalThis.gc !== "function") {
149	    throw new HarnessError("T1_N3_AB_EXPOSE_GC_REQUIRED");
150	  }
151	  return Object.freeze({ cellId, workerCount: Number(workersRaw) });
152	}
153	
154	const AUTHORIZATION = authorize();
155	
156	// ---------------------------------------------------------------------------
157	// Opacity helpers.
158	//
159	// This process holds addresses, passwords, source IPs, verification tokens,
160	// blind-index keys, a KEK, salts, hashes and a secret directory path. None of
161	// them may reach stdout or stderr. Every value that leaves this process passes
162	// through one of the two functions below.
163	// ---------------------------------------------------------------------------
164	
165	/** Our own codes are secret-free by construction and may be reported verbatim. */
166	const OWN_CODE_SHAPE = /^T1_N3_AB_[A-Z0-9_]{1,64}$/;
167	/** Product/infrastructure codes are screaming-snake constants, never payloads. */
168	const GENERIC_CODE_SHAPE = /^[A-Z][A-Z0-9_]{2,63}$/;
169	
170	/**
171	 * Reduces any thrown value to a code that cannot carry a secret.
172	 *
173	 * Error messages are the classic leak: `EMBEDDED_POSTGRES_PROVISIONING_FAILED`
174	 * is safe, but a `pg` error, a filesystem error or a validation error routinely
175	 * embeds a path, an address or a connection string. So a message is reported
176	 * only when it is itself a recognized code, and anything else collapses to a
177	 * single opaque label plus the constructor name.
178	 */
179	function errorCode(error) {
180	  const message = typeof error?.message === "string" ? error.message : "";
181	  if (OWN_CODE_SHAPE.test(message)) return message;
182	  const code = typeof error?.code === "string" ? error.code : "";
183	  if (GENERIC_CODE_SHAPE.test(code)) return code;
184	  if (GENERIC_CODE_SHAPE.test(message)) return message;
185	  return "T1_N3_AB_UNCLASSIFIED_ERROR";
186	}
187	
188	/** The non-secret shape of a failure: a code and the error class name only. */
189	function describeError(error) {
190	  const name = typeof error?.name === "string" && /^[A-Za-z][A-Za-z0-9]{0,63}$/.test(error.name)
191	    ? error.name
192	    : "Error";
193	  return Object.freeze({ code: errorCode(error), errorClass: name });
194	}
195	
196	/**
197	 * Ordinal-free summary of a numeric sample series.
198	 *
199	 * Raw per-sample arrays are deliberately NOT reported: an index into a sample
200	 * array is an ordinal that can be correlated back to a specific request or job,
201	 * which is exactly what the packet forbids. Percentiles carry the measurement
202	 * without carrying the correlation.
203	 */
204	function summarize(samples) {
205	  if (samples.length === 0) {
206	    return Object.freeze({ count: 0, min: null, max: null, mean: null, p50: null, p95: null, p99: null });
207	  }
208	  const sorted = [...samples].sort((left, right) => left - right);
209	  const at = (fraction) => sorted[Math.min(sorted.length - 1, Math.ceil(fraction * sorted.length) - 1)];
210	  const total = sorted.reduce((sum, value) => sum + value, 0);
211	  return Object.freeze({
212	    count: sorted.length,
213	    min: sorted[0],
214	    max: sorted[sorted.length - 1],
215	    mean: total / sorted.length,
216	    p50: at(0.5),
217	    p95: at(0.95),
218	    p99: at(0.99)
219	  });
220	}
221	
222	// ---------------------------------------------------------------------------
223	// stdout discipline.
224	//
225	// `startTestDatabase` forwards embedded-PostgreSQL server logs through
226	// `console.info`, and `console.info` writes to stdout. The packet requires that
227	// stdout carry exactly one final JSON object preceded only by a stable marker,
228	// so every console channel is redirected to stderr for the whole run. Nothing is
229	// discarded: the wrapper captures stdout and stderr together and the adjudicator
230	// scans both, so this only moves the noise, it never hides it.
231	// ---------------------------------------------------------------------------
232	
233	const CONSOLE_CHANNELS = Object.freeze(["log", "info", "debug", "warn", "trace"]);
234	const originalConsole = new Map();
235	
236	function redirectConsoleToStderr() {
237	  for (const channel of CONSOLE_CHANNELS) {
238	    originalConsole.set(channel, console[channel]);
239	    console[channel] = (...args) => {
240	      process.stderr.write(`[T1_N3_AB_CONSOLE ${channel}] ${args.map(String).join(" ")}\n`);
241	    };
242	  }
243	}
244	
245	function restoreConsole() {
246	  for (const [channel, original] of originalConsole) console[channel] = original;
247	  originalConsole.clear();
248	}
249	
250	// ---------------------------------------------------------------------------
251	// Product module loading.
252	//
253	// Imported dynamically, after the gate, from the repository root four levels
254	// above this mission-log directory. `--import tsx` is what makes the TypeScript
255	// sources loadable; this file itself is plain ESM so `node --check` can parse it
256	// without a loader.
257	// ---------------------------------------------------------------------------
258	
259	const REPOSITORY_ROOT = new URL("../../../../", import.meta.url);
260	
261	function moduleHref(relativePath) {
262	  return new URL(relativePath, REPOSITORY_ROOT).href;
263	}
264	
265	async function loadProductModules() {
266	  const [crypto, db, register, registration, mailChannel, testDatabase] = await Promise.all([
267	    import(moduleHref("packages/crypto/src/index.ts")),
268	    import(moduleHref("packages/db/src/index.ts")),
269	    import(moduleHref("packages/register/src/auth-policy.ts")),
270	    import(moduleHref("apps/api/src/registration.ts")),
271	    import(moduleHref("apps/api/src/mail-channel.ts")),
272	    import(moduleHref("tests/support/testDatabase.ts"))
273	  ]);
274	  return Object.freeze({
275	    Argon2WorkerPool: crypto.Argon2WorkerPool,
276	    AuditContextHasher: crypto.AuditContextHasher,
277	    FileUserDekStore: crypto.FileUserDekStore,
278	    loadKek: crypto.loadKek,
279	    migrate: db.migrate,
280	    PostgresIdentityRepository: db.PostgresIdentityRepository,
281	    AUTH_POLICY_REGISTER_ROWS: register.AUTH_POLICY_REGISTER_ROWS,
282	    authPolicyFromRegisterRows: register.authPolicyFromRegisterRows,
283	    InProcessAuthRateLimiter: registration.InProcessAuthRateLimiter,
284	    RegistrationService: registration.RegistrationService,
285	    MemoryMailSender: mailChannel.MemoryMailSender,
286	    startTestDatabase: testDatabase.startTestDatabase
287	  });
288	}
289	
290	// ---------------------------------------------------------------------------
291	// Limiter occupancy: structural page-touch, not a counter bump.
292	//
293	// The limiter holds four preallocated typed arrays. `occupiedSlotsByRoute` is a
294	// bookkeeping counter over them. Setting that counter to 1,572,864 would produce
295	// a report that CLAIMS full occupancy while every expiry page stayed untouched
296	// and unresident — which is precisely the measurement fraud the packet names.
297	// So the sweep writes real values into the count, head, saturation and expiry
298	// arrays, and then re-derives occupancy by SCANNING those arrays rather than
299	// trusting the counter it just wrote.
300	// ---------------------------------------------------------------------------
301	
302	const LIMITER_STRUCTURAL_FIELDS = Object.freeze([
303	  "slotCounts", "slotHeads", "slotSaturatedUntil", "slotExpiries",
304	  "slotOffsetByRoute", "expiryOffsetByRoute", "occupiedSlotsByRoute"
305	]);
306	
307	/**
308	 * A read/write view of the limiter's preallocated state.
309	 *
310	 * This is a test-only structural view of an existing instance, exactly like the
311	 * `limiterMemoryOccupancy` probe in the governed integration test. It adds no
312	 * product API and mutates no product source. If the shape ever stops matching,
313	 * the harness fails closed rather than measuring something it does not
314	 * understand.
315	 */
316	function limiterStructuralView(limiter) {
317	  for (const field of LIMITER_STRUCTURAL_FIELDS) {
318	    if (limiter[field] === undefined) throw new HarnessError("T1_N3_AB_LIMITER_SHAPE_UNRECOGNISED");
319	  }
320	  return limiter;
321	}
322	
323	/**
324	 * Clears the limiter to an exact, provable 0% occupancy.
325	 *
326	 * Scope is deliberate. `slotCounts`, `slotHeads` and `slotSaturatedUntil` are
327	 * zeroed in FULL, because a single stale saturation timestamp anywhere would
328	 * keep a slot occupied and make the 0% label a lie. `slotExpiries` is left
329	 * exactly as the ten registrations left it: `activeCount` never reads an expiry
330	 * for a slot whose count is zero, so the reset is logically complete without
331	 * it — and bulk-filling 17,301,504 doubles here would make every later page a
332	 * pre-touched page and quietly flatten the whole sweep to nothing.
333	 */
334	function resetLimiterOccupancy(limiter) {
335	  const view = limiterStructuralView(limiter);
336	  view.slotCounts.fill(0);
337	  view.slotHeads.fill(0);
338	  view.slotSaturatedUntil.fill(0);
339	  for (const route of AUTH_ROUTE_NAMES) view.occupiedSlotsByRoute[route] = 0;
340	  return Object.freeze({
341	    zeroedSlotElements: view.slotCounts.length + view.slotHeads.length
342	      + view.slotSaturatedUntil.length,
343	    expiryElementsLeftAsRegistered: view.slotExpiries.length
344	  });
345	}
346	
347	/**
348	 * Occupies the first `fraction` of every route's slot row and touches every
349	 * expiry page those slots address.
350	 *
351	 * Each occupied slot is given a full admission ring: `admissionPerSource`
352	 * entries at the far-future sentinel. That is what makes the expiry array
353	 * resident rather than reserved, and it is why the 100% step writes all
354	 * 17,301,504 expiry doubles instead of 1,572,864 of them.
355	 */
356	function applyLimiterOccupancy(limiter, policy, numerator, denominator) {
357	  const view = limiterStructuralView(limiter);
358	  const perRoute = policy.rateLimitBucketCapacity;
359	  const target = Math.floor((perRoute * numerator) / denominator);
360	  let touchedSlotElements = 0;
361	  let touchedExpiryElements = 0;
362	  for (const route of AUTH_ROUTE_NAMES) {
363	    const limit = policy.rateLimits[route].admissionPerSource;
364	    const slotOffset = view.slotOffsetByRoute[route];
365	    const expiryOffset = view.expiryOffsetByRoute[route];
366	    for (let slot = 0; slot < target; slot += 1) {
367	      const index = slotOffset + slot;
368	      view.slotCounts[index] = limit;
369	      view.slotHeads[index] = 0;
370	      view.slotSaturatedUntil[index] = OCCUPANCY_SENTINEL_MS;
371	      touchedSlotElements += 3;
372	      const expiryBase = expiryOffset + slot * limit;
373	      for (let entry = 0; entry < limit; entry += 1) {
374	        view.slotExpiries[expiryBase + entry] = OCCUPANCY_SENTINEL_MS;
375	        touchedExpiryElements += 1;
376	      }
377	    }
378	    view.occupiedSlotsByRoute[route] = target;
379	  }
380	  return Object.freeze({ targetPerRoute: target, touchedSlotElements, touchedExpiryElements });
381	}
382	
383	/**
384	 * Re-derives occupancy from the arrays themselves.
385	 *
386	 * The counter the sweep just wrote is not evidence. This scan is: it counts
387	 * slots that are genuinely non-empty and expiry entries that genuinely hold the
388	 * sentinel, so a counter-only mutation of the sweep is visible as a mismatch
389	 * between `reportedOccupiedSlots` and `scannedOccupiedSlots`.
390	 */
391	function scanLimiterOccupancy(limiter, policy) {
392	  const view = limiterStructuralView(limiter);
393	  let scannedOccupiedSlots = 0;
394	  let scannedSentinelExpiries = 0;
395	  for (const route of AUTH_ROUTE_NAMES) {
396	    const limit = policy.rateLimits[route].admissionPerSource;
397	    const slotOffset = view.slotOffsetByRoute[route];
398	    const expiryOffset = view.expiryOffsetByRoute[route];
399	    for (let slot = 0; slot < policy.rateLimitBucketCapacity; slot += 1) {
400	      const index = slotOffset + slot;
401	      if (view.slotCounts[index] > 0 || view.slotSaturatedUntil[index] > 0) scannedOccupiedSlots += 1;
402	      const expiryBase = expiryOffset + slot * limit;
403	      for (let entry = 0; entry < limit; entry += 1) {
404	        if (view.slotExpiries[expiryBase + entry] === OCCUPANCY_SENTINEL_MS) scannedSentinelExpiries += 1;
405	      }
406	    }
407	  }
408	  const reported = limiter.memoryOccupancy();
409	  return Object.freeze({
410	    scannedOccupiedSlots,
411	    scannedSentinelExpiries,
412	    reportedOccupiedSlots: reported.occupiedSlots,
413	    reportedSlotCapacity: reported.slotCapacity,
414	    reportedPerRouteSlotCapacity: reported.perRouteSlotCapacity,
415	    reportedAllocatedBytes: reported.allocatedBytes
416	  });
417	}
418	
419	// ---------------------------------------------------------------------------
420	// Whole-process observation.
421	// ---------------------------------------------------------------------------
422	
423	/**
424	 * One RSS reading, plus the safety verdict for it.
425	 *
426	 * Every RSS read in this file goes through here, so the 512 MiB stop cannot be
427	 * bypassed by a code path that happens to read `process.memoryUsage()` directly.
428	 */
429	function makeRssObserver() {
430	  const state = { peakBytes: 0, exceeded: false, exceededAtBytes: null };
431	  return Object.freeze({
432	    state,
433	    observe() {
434	      const rss = process.memoryUsage.rss();
435	      if (rss > state.peakBytes) state.peakBytes = rss;
436	      if (rss > RSS_SAFETY_LIMIT_BYTES && !state.exceeded) {
437	        state.exceeded = true;
438	        state.exceededAtBytes = rss;
439	      }
440	      return rss;
441	    },
442	    assertWithinSafety() {
443	      if (state.exceeded) throw new HarnessError("T1_N3_AB_RSS_SAFETY_EXCEEDED");
444	    }
445	  });
446	}
447	
448	/** Forces a real major collection and lets one macrotask turn settle after it. */
449	async function collectGarbage() {
450	  const options = Object.freeze({ type: "major", execution: "sync", flavor: "last-resort" });
451	  globalThis.gc(options);
452	  globalThis.gc(options);
453	  await new Promise((resolve) => setImmediate(resolve));
454	}
455	
456	/**
457	 * Waits until the pool reports no outstanding work, then collects.
458	 *
459	 * Worker threads own 64 MiB Argon2 arenas that a main-thread collection can
460	 * neither see nor quiesce, so an RSS reading taken with jobs in flight measures
461	 * arena churn rather than retention. Every quiesced sample point in this harness
462	 * passes through here, which is what makes those readings order-independent.
463	 */
464	async function quiesce(pool, rss) {
465	  const startedAt = performance.now();
466	  while (pool.stats().outstandingTotal > 0) {
467	    if (performance.now() - startedAt > QUIESCE_TIMEOUT_MS) {
468	      throw new HarnessError("T1_N3_AB_QUIESCE_TIMEOUT");
469	    }
470	    rss.observe();
471	    await new Promise((resolve) => setTimeout(resolve, SAMPLE_INTERVAL_MS));
472	  }
473	  await collectGarbage();
474	  return performance.now() - startedAt;
475	}
476	
477	/**
478	 * Reads the distinct non-main thread identifiers the pool currently owns.
479	 *
480	 * The identifiers themselves are never reported — only their count and the
481	 * main-thread-fallback verdict. A worker thread id is not a secret, but it is an
482	 * ordinal that correlates cells to each other, and the packet's report surface
483	 * is thread-count statistics rather than thread identity.
484	 */
485	function threadEvidence(pool) {
486	  const slots = pool.slots;
487	  if (!Array.isArray(slots)) throw new HarnessError("T1_N3_AB_POOL_SHAPE_UNRECOGNISED");
488	  const ids = new Set();
489	  let mainThreadFallback = false;
490	  let slotsWithoutHandle = 0;
491	  for (const slot of slots) {
492	    const handle = slot.handle;
493	    if (handle === undefined) {
494	      slotsWithoutHandle += 1;
495	      continue;
496	    }
497	    const threadId = handle.threadId;
498	    if (typeof threadId !== "number") throw new HarnessError("T1_N3_AB_POOL_SHAPE_UNRECOGNISED");
499	    // Thread id 0 is the main thread. A pool slot reporting it would mean the
500	    // KDF ran inline on the event loop, which invalidates every timing here.
501	    if (threadId === 0) mainThreadFallback = true;
502	    ids.add(threadId);
503	  }
504	  return Object.freeze({
505	    slotCount: slots.length,
506	    slotsWithoutHandle,
507	    distinctNonMainThreadCount: [...ids].filter((id) => id !== 0).length,
508	    mainThreadFallback
509	  });
510	}
511	
512	/** The pool-state fields this harness reports. Never job or request identity. */
513	function poolSnapshot(stats) {
514	  return Object.freeze({
515	    state: stats.state,
516	    workers: stats.workers,
517	    readyWorkers: stats.readyWorkers,
518	    liveHandles: stats.liveHandles,
519	    retiringHandles: stats.retiringHandles,
520	    active: stats.active,
521	    queuedCredential: stats.queuedCredential,
522	    queuedTotal: stats.queuedTotal,
523	    outstandingCredential: stats.outstandingCredential,
524	    outstandingTotal: stats.outstandingTotal,
525	    restartsInWindow: stats.restartsInWindow,
526	    breakerTripped: stats.breakerTripped
527	  });
528	}
529	
530	// ---------------------------------------------------------------------------
531	// The run.
532	// ---------------------------------------------------------------------------
533	
534	/**
535	 * Holder for the partial measurement record of a failed run.
536	 *
