597	function gateSecrets(bundle, failures) {
598	  const scan = bundle.secretScan ?? {};
599	  const literals = Array.isArray(scan.generatedLiterals) ? scan.generatedLiterals : null;
600	  const headers = Array.isArray(scan.declaredShaHeaders) ? scan.declaredShaHeaders : [];
601	  if (literals === null || literals.length === 0) {
602	    // An empty literal set would make the scan vacuous while still reporting
603	    // clean, which is the same failure mode as not scanning at all.
604	    failures.add("secret", "generated-literal-set-declared");
605	    return;
606	  }
607	  for (const header of headers) {
608	    if (!DECLARED_SHA_HEADER_SHAPES.some((shape) => shape.test(header))) {
609	      failures.add("custody", "whitelist-contains-only-declared-sha-headers");
610	    }
611	  }
612	  const receipts = bundle.receiptSources;
613	  let scanned = 0;
614	  for (const receipt of receipts) {
615	    // Both streams, complete, every time. Scanning stdout alone is how a leak
616	    // printed by a failing assertion — which lands on stderr — stays invisible.
617	    if (typeof receipt.stdout !== "string" || typeof receipt.stderr !== "string") {
618	      failures.add("receipt", "complete-stdout-and-stderr-captured", {
619	        cell: shortLabel(receipt.cellId)
620	      });
621	      continue;
622	    }
623	    // T1-N3-AB-ANCHOR-M10-SECRET-SCAN
624	    const hits = scanReceiptBody(`${receipt.stdout}\n${receipt.stderr}`, literals, headers);
625	    scanned += 1;
626	    for (const hit of hits) {
627	      failures.add("secret", hit.kind === "generated-literal"
628	        ? "no-generated-literal-in-receipt"
629	        : `no-forbidden-${hit.name}-in-receipt`, {
630	        cell: shortLabel(receipt.cellId), occurrences: hit.occurrences
631	      });
632	    }
633	  }
634	  // Integrity of the loop itself: every scannable receipt must have been
635	  // visited. This catches a `continue`, an early `break` or a sliced receipt
636	  // list. It does NOT catch mutant 10, which leaves the loop intact and empties
637	  // the hit list — that one is caught by the self-test fixtures, where the
638	  // planted leak stops being reported and `guard-fires:` fails.
639	  if (scanned !== receipts.filter((receipt) =>
640	    typeof receipt.stdout === "string" && typeof receipt.stderr === "string").length) {
641	    failures.add("secret", "full-receipt-secret-scan-executed", {
642	      scanned, available: receipts.length
643	    });
