--- a/tests/integration/registration-database.test.ts (wrapper entry backup)
+++ b/tests/integration/registration-database.test.ts (temporary diagnostic)
@@ -4091,7 +4091,784 @@
       );
     }
   }, 300_000);
+
+
+  // ---------------------------------------------------------------------------
+  // TEMPORARY DIAGNOSTIC — T1 N=3 critical-path attribution.
+  // Added under logs/T1-claude-n3-attribution-packet.md, removed and restored
+  // byte-for-byte from the wrapper-owned entry backup before the seat exits.
+  // Diagnostic only: no product, policy, threshold, cadence, queue, worker, KDF
+  // or database behaviour is changed, and no permanent test is touched.
+  // ---------------------------------------------------------------------------
+  it("T1 rework8 D1 attributes the real N=3 registration critical path", async () => {
+    const { AsyncLocalStorage } = await import("node:async_hooks");
+    type Arm = "existing" | "missing";
+    type Phase = "request" | "critical-provision" | "postresponse";
+    interface RequestScope {
+      readonly ordinal: number;
+      readonly arm: Arm;
+      readonly phase: Phase;
+    }
+    const als = new AsyncLocalStorage<RequestScope>();
+
+    const registrationCadenceMs = basePolicy.channel.registrationMailDispatchActivationSpacingMs;
+    const clampMs = basePolicy.verification.enumerationResponseFloorMs
+      + basePolicy.verification.enumerationToleranceMs;
+    const password = "correct horse battery staple";
+    const pool = sharedArgon2Pool();
+
+    // -- identifier-safe console capture -------------------------------------
+    // Installed BEFORE the N1/N2 preconditioning and retained through the final
+    // drain. Captured text is never emitted verbatim; only whitelisted
+    // bracketed error-code counts are printed.
+    const captured: string[] = [];
+    const originalConsoleError = console.error;
+    const originalConsoleWarn = console.warn;
+    const captureLine = (args: readonly unknown[]): void => {
+      captured.push(args.map((value) => {
+        if (typeof value === "string") return value;
+        try {
+          return JSON.stringify(value) ?? String(value);
+        } catch {
+          return "[uninspectable]";
+        }
+      }).join(" "));
+    };
+    console.error = (...args: unknown[]): void => { captureLine(args); };
+    console.warn = (...args: unknown[]): void => { captureLine(args); };
+
+    const rejections: string[] = [];
+    const onUnhandled = (reason: unknown): void => {
+      rejections.push(typeof (reason as { code?: unknown })?.code === "string"
+        ? String((reason as { code?: unknown }).code)
+        : "UNTYPED");
+    };
+    process.on("unhandledRejection", onUnhandled);
+
+    // -- measurement state ----------------------------------------------------
+    interface Span {
+      readonly ordinal: number;
+      readonly arm: Arm;
+      readonly phase: Phase;
+      readonly stage: string;
+      readonly start: number;
+      readonly end: number;
+    }
+    const spans: Span[] = [];
+    const requestStart = new Map<number, number>();
+    const requestSettled = new Map<number, number>();
+    const requestArm = new Map<number, Arm>();
+    const requestWave = new Map<number, number>();
+    const clampRequestedMs = new Map<number, number>();
+    const auditOrderWithinRequest = new Map<number, number>();
+    const outcomes = new Map<number, string>();
+    let recording = false;
+
+    const record = (stage: string, start: number, end: number, scope?: RequestScope): void => {
+      if (!recording || scope === undefined) return;
+      spans.push({
+        ordinal: scope.ordinal, arm: scope.arm, phase: scope.phase, stage, start, end
+      });
+    };
+
+    // -- pool sampling and event-loop heartbeat -------------------------------
+    let poolSamples = 0;
+    let poolMaxActive = 0;
+    let poolMaxQueuedCredential = 0;
+    let poolMaxQueuedAudit = 0;
+    let poolMaxQueuedTotal = 0;
+    let poolMaxOutstandingCredential = 0;
+    let poolMaxOutstandingAudit = 0;
+    let poolMaxOutstandingTotal = 0;
+    const loopDelays: number[] = [];
+    let poolSampler: ReturnType<typeof setInterval> | undefined;
+    let loopHeartbeat: ReturnType<typeof setInterval> | undefined;
+    let lastBeatAt = 0;
+    const startObservers = (): void => {
+      if (poolSampler !== undefined) return;
+      poolSampler = setInterval(() => {
+        const stats = pool.stats();
+        poolSamples += 1;
+        poolMaxActive = Math.max(poolMaxActive, stats.active);
+        poolMaxQueuedCredential = Math.max(poolMaxQueuedCredential, stats.queuedCredential);
+        poolMaxQueuedAudit = Math.max(poolMaxQueuedAudit, stats.queuedAudit);
+        poolMaxQueuedTotal = Math.max(poolMaxQueuedTotal, stats.queuedTotal);
+        poolMaxOutstandingCredential = Math.max(
+          poolMaxOutstandingCredential, stats.outstandingCredential
+        );
+        poolMaxOutstandingAudit = Math.max(poolMaxOutstandingAudit, stats.outstandingAudit);
+        poolMaxOutstandingTotal = Math.max(poolMaxOutstandingTotal, stats.outstandingTotal);
+      }, 5);
+      lastBeatAt = performance.now();
+      loopHeartbeat = setInterval(() => {
+        const now = performance.now();
+        loopDelays.push(Math.max(0, now - lastBeatAt - 1));
+        lastBeatAt = now;
+      }, 1);
+    };
+    const stopObservers = (): void => {
+      if (poolSampler !== undefined) clearInterval(poolSampler);
+      if (loopHeartbeat !== undefined) clearInterval(loopHeartbeat);
+      poolSampler = undefined;
+      loopHeartbeat = undefined;
+    };
+
+    // -- process-owned pool wrappers (installed once, restored in finally) ----
+    const originalHashPassword = pool.hashPassword.bind(pool);
+    const originalHashAuditContext = pool.hashAuditContext.bind(pool);
+    const poolSurface = pool as unknown as {
+      hashPassword: typeof pool.hashPassword;
+      hashAuditContext: typeof pool.hashAuditContext;
+    };
+    poolSurface.hashPassword = async (value, salt, parameters) => {
+      const scope = als.getStore();
+      const start = performance.now();
+      try {
+        return await originalHashPassword(value, salt, parameters);
+      } finally {
+        record("pool.hashPassword", start, performance.now(), scope);
+      }
+    };
+    poolSurface.hashAuditContext = async (value, salt, parameters) => {
+      const scope = als.getStore();
+      let stage = "pool.hashAuditContext.postresponse";
+      if (scope !== undefined && scope.phase === "critical-provision") {
+        const order = (auditOrderWithinRequest.get(scope.ordinal) ?? 0) + 1;
+        auditOrderWithinRequest.set(scope.ordinal, order);
+        // First and second invocation ORDER inside one request, never a value.
+        stage = order === 1
+          ? "pool.hashAuditContext.first"
+          : order === 2 ? "pool.hashAuditContext.second" : `pool.hashAuditContext.extra${order}`;
+      }
+      const start = performance.now();
+      try {
+        return await originalHashAuditContext(value, salt, parameters);
+      } finally {
+        record(stage, start, performance.now(), scope);
+      }
+    };
+
+    // -- the original S3b cell, uninstrumented, for N=1 and N=2 history -------
+    const runHistoryCell = async (concurrency: 1 | 2): Promise<void> => {
+      const waves = concurrency === 1 ? 8 : 4;
+      const existingGroups = Math.ceil(waves / 4);
+      const historyMail = new MemoryMailSender();
+      const flow = buildService({ mail: historyMail });
+      const existingEmails = Array.from(
+        { length: concurrency * existingGroups },
+        (_, index) => `t1-n3attr-n${concurrency}-existing-${index}@example.test`
+      );
+      await Promise.all(existingEmails.map((email, index) => flow.service.register({
+        email,
+        password,
+        recoveryEmail: `t1-n3attr-n${concurrency}-seed-${index}-recovery@example.test`,
+        adultAffirmed: true
+      }, {
+        ip: `203.0.${concurrency}.${index + 1}`,
+        userAgent: "vitest-s3b-timing-seed",
+        requestId: `request:s3b:timing:n${concurrency}:seed:${index}`
+      })));
+      await flow.service.drainMailDispatches();
+      const runExistingWave = async (wave: number): Promise<void> => {
+        await Promise.all(Array.from({ length: concurrency }, async (_, index) => {
+          const email = existingEmails[(wave % existingGroups) * concurrency + index]!;
+          await flow.service.register({
+            email,
+            password,
+            recoveryEmail: `t1-n3attr-n${concurrency}-existing-${index}-recovery@example.test`,
+            adultAffirmed: true
+          }, {
+            ip: `203.${concurrency}.${wave}.${index + 1}`,
+            userAgent: "vitest-s3b-timing-existing",
+            requestId: `request:s3b:timing:n${concurrency}:existing:${wave}:${index}`
+          });
+        }));
+      };
+      const runMissingWave = async (wave: number): Promise<void> => {
+        await Promise.all(Array.from({ length: concurrency }, async (_, index) => {
+          await flow.service.register({
+            email: `t1-n3attr-n${concurrency}-missing-${wave}-${index}@example.test`,
+            password,
+            recoveryEmail: `t1-n3attr-n${concurrency}-missing-${wave}-${index}-recovery@example.test`,
+            adultAffirmed: true
+          }, {
+            ip: `204.${concurrency}.${wave}.${index + 1}`,
+            userAgent: "vitest-s3b-timing-missing",
+            requestId: `request:s3b:timing:n${concurrency}:missing:${wave}:${index}`
+          });
+        }));
+      };
+      for (let wave = 0; wave < waves; wave += 1) {
+        if (wave % 2 === 0) {
+          await runExistingWave(wave);
+          await runMissingWave(wave);
+        } else {
+          await runMissingWave(wave);
+          await flow.service.drainMailDispatches();
+          await runExistingWave(wave);
+        }
+        await flow.service.drainMailDispatches();
+      }
+    };

+    const knownFailureCodes = new Set([
+      "AUTH_INPUT_INVALID", "AUTH_RATE_LIMITED", "AUTH_MAIL_BUSY",
+      "AUTH_REGISTRATION_FAILED", "AUTH_TEMPORARILY_UNAVAILABLE"
+    ]);
+
+    let restoreService: (() => void) | undefined;
+    try {
+      // 1. N=1 and N=2 cell history, exactly as the original orders them.
+      await runHistoryCell(1);
+      await runHistoryCell(2);
+
+      // 2. The N=3 cell, instrumented.
+      const concurrency = 3 as const;
+      const waves = 4;
+      const existingGroups = Math.ceil(waves / 4);
+      const timingMail = new MemoryMailSender();
+      const flow = buildService({ mail: timingMail });
+
+      const serviceSurface = flow.service as unknown as {
+        provisionPendingAccount(input: unknown): Promise<unknown>;
+        reserveMailDispatchPermit(
+          correlationId: string, minimumReservationMs?: number, activationSpacingMs?: number
+        ): Promise<unknown>;
+        scheduleRegistrationHash(value: string): {
+          readonly promise: Promise<string>;
+          readonly cancel: () => void;
+        };
+        holdRegistrationEnumerationClamp(startedAt: number): Promise<void>;
+      };
+      const repositorySurface = flow.repository as unknown as {
+        findAuditIdentityByBlindIndex(emailBlindIndex: Buffer): Promise<unknown>;
+        prepareAuditContext(source: unknown): Promise<unknown>;
+        transaction<T>(operation: (client: unknown) => Promise<T>): Promise<T>;
+        createPendingAccount(input: unknown, beforeCommit: () => Promise<void>): Promise<unknown>;
+      };
+      const originalProvision = serviceSurface.provisionPendingAccount.bind(flow.service);
