/** Artifacts whose bytes must match the launch authority exactly. */
const GOVERNED_ARTIFACTS = Object.freeze([
  "T1-3worker-ab-booted-rss-harness.mjs",
  "T1-3worker-ab-adjudicator.mjs",
  "T1-3worker-ab-command-matrix.md",
