const STANDALONE_SENTINEL_EXPIRY_ENTRIES = 17_301_504;
const STANDALONE_OCCUPANCY_LABELS = Object.freeze(["0", "25", "50", "100"]);
const STANDALONE_REGISTRATIONS = 10;
const STANDALONE_MAX_COST_JOBS = 8;

