    },
    candidateRssBound: { status: REQUIRED_RSS_BOUND_LABEL },
    integrationCells,
    architectureResourceCells,
    architectureFaultCells,
    standaloneCells,
    retainedAllocationControl,
    vitestMutants,
    adjudicatorMutants,
