  "mutant-01-enqueue-reported-as-dispatch",
  "mutant-02-settlement-reported-as-dispatch",
  "mutant-03-omit-one-credential-job-from-ordinal-map",
  "mutant-04-secretly-keep-two-workers-in-three-worker-cell",
