  integration: "[T1_N3_AB_INTEGRATION_REPORT]",
  architecture: "[T1_N3_AB_ARCHITECTURE_REPORT]",
  fault: "[T1_N3_AB_FAULT_REPORT]",
  standalone: "[T1_N3_AB_STANDALONE_REPORT]"
