  const Q = workers === 2 ? 200 : 20;
  return {
    cellId: `integration-p${pairIndex + 1}-a${armIndex}-w${workers}`,
    workers,
    pairIndex: pairIndex + 1,
    armIndex,
    rawStatus: 0,
