  const report = faultName === "fault-unconfirmed-death"
    ? { ...base, breakerTripped: true, closeRejectedTyped: true, retainedRetiringHandles: 1 }
    : faultName === "fault-late-exit-before-close"
      ? { ...base, replacementsSpawned: 1 }
