/**
 * The only whitelistable shape: a declared temporary SHA header.
 *
 * Nothing else may be whitelisted, and a whitelist entry that does not match one
 * of these two forms is itself a custody failure rather than a silently ignored
 * line. Without this restriction a wrapper could whitelist an address and the
 * scan would report clean.
 */
const WHITELISTABLE_SHA_HEADER_NAMES = Object.freeze([
  "T1_N3_AB_PACKET_SHA256",
  "T1_N3_AB_INTEGRATION_PATCH_SHA256",
  "T1_N3_AB_ARCHITECTURE_PATCH_SHA256",
  "T1_N3_AB_HARNESS_SHA256",
  "T1_N3_AB_ADJUDICATOR_SHA256",
  "T1_N3_AB_MATRIX_SHA256",
  "T1_N3_AB_HELPER_SHA256",
  "T1_N3_AB_BUILDER_SHA256",
  "T1_N3_AB_WRAPPER_SHA256",
  "T1_N3_AB_LAUNCH_AUTHORITY_SHA256"
]);

/**
 * A whitelist entry is lawful only if it is one of the exact named header lines
 * above, carrying a 64-hex digest. It is NOT a shape family the manifest can
 * expand: a run cannot invent `T1_N3_AB_ANYTHING_SHA256` and whitelist it, and
 * the total number of entries can never exceed the number of names this
 * adjudicator owns.
 */
function isDeclaredShaHeader(line) {
  const match = /^\[([A-Z0-9_]{1,64})\] ([0-9a-f]{64})$/.exec(line);
  return match !== null && WHITELISTABLE_SHA_HEADER_NAMES.includes(match[1]);
