/** Beta quantile by bisection. Monotone, so bisection is exact to 1e-12 here. */
function betaQuantile(probability, a, b) {
  let low = 0;
  let high = 1;
  for (let iteration = 0; iteration < 200; iteration += 1) {
    const middle = (low + high) / 2;
