  const missing = [];
  for (const [field, kind] of Object.entries(specification)) {
    const value = object?.[field];
    const ok = kind === "number"
      ? isFiniteNumber(value)
      : kind === "integer"
        ? Number.isInteger(value)
        : kind === "boolean"
          ? typeof value === "boolean"
          : kind === "string"
            ? typeof value === "string" && value.length > 0
            : kind === "array"
              ? Array.isArray(value)
