    rawStatus: 0,
    stdout: SELF_TEST_CLEAN_RECEIPT_STDOUT,
    stderr: SELF_TEST_CLEAN_RECEIPT_STDERR,
    report: null
  };
  return {
    packetSha256: EXPECTED_PACKET_SHA256,
