      },
      temporaryTests: Object.fromEntries(TEMPORARY_TEST_PATHS.map((path) => [path, {
        backupSha256: GOVERNED_HASHES[path],
        restoredSha256: GOVERNED_HASHES[path],
        temporaryDiffSha256: "3".repeat(64),
        cmpIdentical: true,
