/**
 * Every run stream in the mission logs directory, read straight off disk.
 *
 * Derived from the directory rather than from a manifest list on purpose: a
 * manifest that enumerated the streams to scan could omit the one that leaked.
 * The single exclusion is the wrapper-owned literal carrier, which by
 * construction contains every generated literal and is destroyed after this
 * program returns.
 */
function auxiliaryReceipts(manifestReal, carrierReal) {
  const root = realpathSync(MISSION_LOGS_DIR);
  const entries = [];
  for (const name of readdirSync(root).sort()) {
    if (!name.startsWith("T1-3worker-ab-")) continue;
    const full = resolve(root, name);
    if (full === carrierReal) continue;
    let body;
    try {
      body = readFileSync(full, "utf8");
    } catch {
      continue;
    }
    entries.push({
      cellId: basename(name),
      isManifest: full === manifestReal,
      stdout: body,
      stderr: "",
      report: null
    });
  }
  return entries;
}

