    corrupt: (bundle) => { bundle.custody.governedHashes["apps/api/src/main.ts"] = "0".repeat(64); }
  }),
  Object.freeze({
    guard: "whitelist-contains-only-declared-sha-headers", markerClass: "custody",
    corrupt: (bundle) => { bundle.secretScan.declaredShaHeaders = ["someone@example.test"]; }
  }),
  Object.freeze({
    guard: "whitelist-not-expandable-beyond-named-headers", markerClass: "custody",
    corrupt: (bundle) => {
      bundle.secretScan.declaredShaHeaders = Array.from({ length: 24 }, () =>
        `[T1_N3_AB_PACKET_SHA256] ${EXPECTED_PACKET_SHA256}`);
    }
