    return 2;
  }

  const verdict = adjudicate(bundle);
  if (verdict.blocked) {
    process.stdout.write(`[T1_N3_AB_FAILED_ASSERTIONS] ${JSON.stringify(verdict.failures)}\n`);
    process.stdout.write(`${verdict.marker}\n`);
