  if (Array.isArray(detail)) return detail.map(sanitizeDetail);
  if (typeof detail === "object") {
    return Object.fromEntries(
      Object.entries(detail)
        .filter(([key]) => /^[A-Za-z0-9_]{1,40}$/.test(key))
        .map(([key, value]) => [key, sanitizeDetail(value)])
