const BLOCKED_PRECEDENCE = Object.freeze([
  "custody", "secret", "rss-safety", "restoration", "receipt", "normal-cell", "mutant"
]);

function blockedMarker(kind) {
  return `CODEX BLOCKED (${kind})`;
